package rpg.engine.core.util; import java.io.*; public final class VarInts { private VarInts(){} public static void write(DataOutput out,long v)throws IOException{while((v&~0x7fL)!=0){out.writeByte((int)((v&0x7f)|0x80));v>>>=7;}out.writeByte((int)v);} public static long read(DataInput in)throws IOException{long r=0;int s=0;for(int i=0;i<10;i++){int b=in.readUnsignedByte();r|=(long)(b&127)<<s;if((b&128)==0)return r;s+=7;}throw new IOException("varint too long");} }
